import{bV as e,aL as r,u as t,G as l}from"./chunks/framework.DvBUyM1S.js";const m=JSON.parse('{"title":"Mac常用软件推荐","description":"","frontmatter":{"title":"Mac常用软件推荐","date":"2018-12-28T00:00:00.000Z","tags":["Mac"],"permalink":"/pages/4eec3f/","categories":[null]},"headers":[],"relativePath":"06.工具/03.Mac/01.Mac常用软件推荐.md","filePath":"06.工具/03.Mac/01.Mac常用软件推荐.md","lastUpdated":1652231681000}'),o={name:"06.工具/03.Mac/01.Mac常用软件推荐.md"};function i(p,a,n,h,c,s){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="mac-开发常用软件推荐" tabindex="-1">Mac 开发常用软件推荐 <a class="header-anchor" href="#mac-开发常用软件推荐" aria-label="Permalink to &quot;Mac 开发常用软件推荐&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>记录入手第一台 Mac，熟悉 Mac 及前端开发历程。</p><h3 id="utools-效率神器" tabindex="-1">uTools 效率神器 <a class="header-anchor" href="#utools-效率神器" aria-label="Permalink to &quot;uTools 效率神器&quot;">​</a></h3><p>uTools 是一个极简、插件化、跨平台的现代桌面软件。通过自由选配丰富的插件，打造你得心应手的工具集合。 这款软件机缘巧合看到用过几天，里面很多小工具确实不错。有取代 Alfred 的趋势。</p><p><img src="http://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20210923-16323905965241.jpg" alt="" loading="lazy"></p><p><a href="https://www.u.tools/" target="_blank" rel="noreferrer">uTools 官网</a></p><p><strong>特性</strong></p><ul><li><p>插件化： 优秀的插件化设计，自取所需。每个插件解决一个具体场景的问题，简洁易用、随用随走。</p></li><li><p>多功能输入框： 支持文本、截图、图片、文件、文件夹</p></li><li><p>自动识别： 自动识别文本类型（json、base64、时间戳等）</p></li><li><p>自动粘贴： 呼出 uTools 时，如果剪切板中 5 秒内有新的内容，将自动粘贴到输入框</p></li></ul><h3 id="alfred-效率神器" tabindex="-1">Alfred 效率神器 <a class="header-anchor" href="#alfred-效率神器" aria-label="Permalink to &quot;Alfred 效率神器&quot;">​</a></h3><p>Alfred 这是一款被称之为 Mac 效率神器的 App，有了 Alfred 你甚至无需鼠标就可以实现各种操作，包括出发各种文件、网络操作，其 UI 界面使用方便，而且不是通过命令来实现，是开发者们和键盘童鞋们的神器，比之此前类似的软件——Pack 和 Power 来说完全是秒杀的节奏。</p><h3 id="quiver-程序猿使用的笔记本" tabindex="-1">Quiver 程序猿使用的笔记本 <a class="header-anchor" href="#quiver-程序猿使用的笔记本" aria-label="Permalink to &quot;Quiver 程序猿使用的笔记本&quot;">​</a></h3><p>Quiver 程序猿使用的笔记本，支持混合书写文本、代码、Markdown 标记等，方便程序员记录笔记和代码片段，并提供全文搜索功能，类似印象笔记的左中右三栏布局，是一款程序猿必备的利器。</p><h3 id="mweb-markdown-写作" tabindex="-1">MWeb Markdown 写作 <a class="header-anchor" href="#mweb-markdown-写作" aria-label="Permalink to &quot;MWeb Markdown 写作&quot;">​</a></h3><p><a href="https://zh.mweb.im/help.html" target="_blank" rel="noreferrer">MWeb 使用教程</a></p><ul><li>可用于搭建个人 Wiki 知识库。</li></ul><h3 id="evernote-印象笔记" tabindex="-1">Evernote 印象笔记 <a class="header-anchor" href="#evernote-印象笔记" aria-label="Permalink to &quot;Evernote 印象笔记&quot;">​</a></h3><ul><li>随时随地获取、整理、分享笔记，让灵感时刻与你同行。</li><li>让生活更有序，让工作更高效，让协作更便捷</li></ul><p><a href="https://www.yinxiang.com/" target="_blank" rel="noreferrer">Evernote 官网</a> <a href="https://www.yinxiang.com/" target="_blank" rel="noreferrer">https://www.yinxiang.com/</a></p><h3 id="magnet-快捷操作窗口-收费" tabindex="-1">Magnet 快捷操作窗口(收费) <a class="header-anchor" href="#magnet-快捷操作窗口-收费" aria-label="Permalink to &quot;Magnet 快捷操作窗口(收费)&quot;">​</a></h3><p><code>Magnet</code>是一款窗口速调辅助工具，拖拽窗口到屏幕边缘可以自动半屏， 全屏或者四分之一屏幕，还可以设定快捷键完成分屏。</p><h3 id="spectacle-快捷操作窗口-免费" tabindex="-1">Spectacle 快捷操作窗口(免费) <a class="header-anchor" href="#spectacle-快捷操作窗口-免费" aria-label="Permalink to &quot;Spectacle 快捷操作窗口(免费)&quot;">​</a></h3><p>免费开源的 App，如果不要求太多的自定义功能，它能够满足绝大部分人的需求了。</p><p><a href="https://www.spectacleapp.com/" target="_blank" rel="noreferrer">Spectacle 官网</a> <a href="https://www.spectacleapp.com/" target="_blank" rel="noreferrer">https://www.spectacleapp.com/</a></p><h3 id="腾讯柠檬" tabindex="-1">腾讯柠檬 <a class="header-anchor" href="#腾讯柠檬" aria-label="Permalink to &quot;腾讯柠檬&quot;">​</a></h3><ul><li>定制化清理方案 强大清理能力</li><li>极简状态栏 实时了解 Mac 系统状况</li><li>清理小工具 软件卸载、相似图片清理、磁盘清理等</li></ul><p><a href="https://lemon.qq.com/" target="_blank" rel="noreferrer">腾讯柠檬 官网</a></p><h3 id="keka-压缩-解压" tabindex="-1">Keka 压缩/解压 <a class="header-anchor" href="#keka-压缩-解压" aria-label="Permalink to &quot;Keka 压缩/解压&quot;">​</a></h3><p>满足 mac os 平台的日常解压缩需求，体积小，简单易用，速度较快。</p><p><a href="https://github.com/aonez/Keka/releases" target="_blank" rel="noreferrer">Keka 官网</a></p><p>下载的入口 <code>Assets``=&gt;``Keka-1.1.26.dmg</code> 下载就对了。</p><h3 id="itycal-日历" tabindex="-1">Itycal 日历 <a class="header-anchor" href="#itycal-日历" aria-label="Permalink to &quot;Itycal 日历&quot;">​</a></h3><p><code>Itycal</code>是一个很小的菜单栏日历。</p><p><img src="http://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20210923-16323906284268.jpg" alt="" loading="lazy"></p><p>如果想实现上图的效果，在输入框填入<code>E h:mm</code>，然后将系统默认时间关闭即可。这样看上去挺美观的。</p><p><a href="https://www.mowglii.com/itsycal/" target="_blank" rel="noreferrer">官网</a> <a href="https://www.mowglii.com/itsycal/" target="_blank" rel="noreferrer">https://www.mowglii.com/itsycal/</a></p><h3 id="iterm2-终端工具" tabindex="-1">iTerm2 终端工具 <a class="header-anchor" href="#iterm2-终端工具" aria-label="Permalink to &quot;iTerm2 终端工具&quot;">​</a></h3><p>Mac OS 自带的终端，用起来虽然有些不太方便，界面也不够友好,iTerm2 是一款相对比较好用的终端工具.iTerm2 常用操作包括主题选择、声明高亮、自动填充建议、隐藏用户名和主机名、分屏效果等。</p><p><a href="https://www.iterm2.com/" target="_blank" rel="noreferrer">iTerm2 官网</a> <a href="https://www.iterm2.com/" target="_blank" rel="noreferrer">https://www.iterm2.com/</a></p><p><a href="https://www.jianshu.com/p/ba08713c2b19" target="_blank" rel="noreferrer">item2 使用教程</a> <a href="https://www.jianshu.com/p/ba08713c2b19" target="_blank" rel="noreferrer">https://www.jianshu.com/p/ba08713c2b19</a></p><h3 id="istat-menus-系统监控" tabindex="-1">iStat Menus 系统监控 <a class="header-anchor" href="#istat-menus-系统监控" aria-label="Permalink to &quot;iStat Menus 系统监控&quot;">​</a></h3><p>iStat Menus 是 Mac 上最优秀的系统监控工具，能够在系统菜单栏实时监控 CPU、GPU、内存、硬盘、网络、温度、电池以及系统时间等，稳定且占用资源少，可以说是装机必备的软件。</p><h3 id="iina-视频播放器" tabindex="-1">IINA 视频播放器 <a class="header-anchor" href="#iina-视频播放器" aria-label="Permalink to &quot;IINA 视频播放器&quot;">​</a></h3><p>IINA 基于 mpv，为最新 Mac 系统而生，支持 Touch Bar、兼容 MPV 脚本、几乎支持所有格式、网络播放，是一款拥有优雅外观的视频播放器。</p><p><a href="https://iina.io/" target="_blank" rel="noreferrer">IINA 官网</a></p><h3 id="popclip-复制功能扩展" tabindex="-1">PopClip 复制功能扩展 <a class="header-anchor" href="#popclip-复制功能扩展" aria-label="Permalink to &quot;PopClip 复制功能扩展&quot;">​</a></h3><p>PopClip 最基本的功能就是复制粘贴的使用，除此之外，再无拓展支持的情况下，根据鼠标选中的内容，PopClip 还自身支持链接的跳转打开、自带词典的翻译、邮件地址跳转、搜索引擎搜索、单词纠正等功能。</p><h3 id="snipaste-截图工具" tabindex="-1">Snipaste 截图工具 <a class="header-anchor" href="#snipaste-截图工具" aria-label="Permalink to &quot;Snipaste 截图工具&quot;">​</a></h3><p>一个简单但强大的截图工具。</p><p><a href="https://zh.snipaste.com/" target="_blank" rel="noreferrer">Snipaste 官网</a></p><h3 id="pap-er-壁纸" tabindex="-1">pap.er 壁纸 <a class="header-anchor" href="#pap-er-壁纸" aria-label="Permalink to &quot;pap.er 壁纸&quot;">​</a></h3><p>每天享受来自全球新鲜精美的壁纸。</p><p><a href="https://paper.meiyuan.in/" target="_blank" rel="noreferrer">pap.er 官网</a></p><h3 id="fliqlo屏保" tabindex="-1">Fliqlo屏保 <a class="header-anchor" href="#fliqlo屏保" aria-label="Permalink to &quot;Fliqlo屏保&quot;">​</a></h3><p><code>Fliqlo</code> 是一款非常简洁的 Mac OS 设备时钟屏保应用程序。</p><p><img src="http://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20210923-16323909684322.jpg" alt="" loading="lazy"></p><p><a href="https://fliqlo.com/#/screensaver" target="_blank" rel="noreferrer">官网</a></p><h3 id="aerial-屏保" tabindex="-1">Aerial 屏保 <a class="header-anchor" href="#aerial-屏保" aria-label="Permalink to &quot;Aerial 屏保&quot;">​</a></h3><p>显示 Apple 在纽约，旧金山，夏威夷，中国等地拍摄的空中电影。</p><p><a href="https://github.com/JohnCoates/Aerial" target="_blank" rel="noreferrer">Aerial 官网</a></p>',60)])])}const u=e(o,[["render",i]]);export{m as __pageData,u as default};
